public readonly record struct Money(long Cents)
{
    public static Money Identity => new(0);
    public static Money Combine(Money a, Money b) => new(a.Cents + b.Cents);
}

public static class MonoidOps
{
    public static T Fold<T>(IEnumerable<T> xs, T identity, Func<T, T, T> combine)
    {
        var acc = identity;
        foreach (var x in xs) acc = combine(acc, x);
        return acc;                       // total: empty input yields Identity
    }
}

